"use strict";

/**
 * MinStack — supports push, pop, top, and getMin, all in O(1) time.
 *
 * Uses a parallel auxiliary stack that tracks the running minimum at each
 * depth so that getMin() is always O(1) without scanning the main stack.
 */
class MinStack {
  constructor() {
    this.stack = [];
    this.minStack = [];
  }

  push(val) {
    this.stack.push(val);
    const currentMin =
      this.minStack.length === 0
        ? val
        : Math.min(val, this.minStack[this.minStack.length - 1]);
    this.minStack.push(currentMin);
  }

  pop() {
    if (this.stack.length === 0) throw new Error("Stack is empty");
    this.minStack.pop();
    return this.stack.pop();
  }

  top() {
    if (this.stack.length === 0) throw new Error("Stack is empty");
    return this.stack[this.stack.length - 1];
  }

  getMin() {
    if (this.minStack.length === 0) throw new Error("Stack is empty");
    return this.minStack[this.minStack.length - 1];
  }

  get size() {
    return this.stack.length;
  }
}

// --- Test Cases ---

function runTests() {
  let passed = 0;
  let failed = 0;

  function assert(condition, name) {
    if (condition) {
      console.log("  PASS: " + name);
      passed++;
    } else {
      console.log("  FAIL: " + name);
      failed++;
    }
  }

  // Basic push/top
  console.log("Basic operations:");
  {
    const s = new MinStack();
    s.push(5);
    assert(s.top() === 5, "top after single push");
    assert(s.getMin() === 5, "getMin after single push");
    assert(s.size === 1, "size is 1");
  }

  // Multiple pushes, getMin tracks minimum
  console.log("Minimum tracking:");
  {
    const s = new MinStack();
    s.push(3);
    s.push(5);
    assert(s.getMin() === 3, "getMin after 3,5");
    s.push(2);
    assert(s.getMin() === 2, "getMin after 3,5,2");
    s.push(1);
    assert(s.getMin() === 1, "getMin after 3,5,2,1");
  }

  // Pop restores previous minimum
  console.log("Pop restores min:");
  {
    const s = new MinStack();
    s.push(3);
    s.push(1);
    s.push(4);
    assert(s.getMin() === 1, "min is 1 before pop");
    s.pop(); // remove 4
    assert(s.getMin() === 1, "min still 1 after popping 4");
    s.pop(); // remove 1
    assert(s.getMin() === 3, "min restored to 3 after popping 1");
  }

  // Top returns correct value after multiple operations
  console.log("Top correctness:");
  {
    const s = new MinStack();
    s.push(10);
    s.push(20);
    assert(s.top() === 20, "top is 20");
    s.pop();
    assert(s.top() === 10, "top is 10 after pop");
  }

  // Duplicate values
  console.log("Duplicate values:");
  {
    const s = new MinStack();
    s.push(2);
    s.push(2);
    assert(s.getMin() === 2, "min with duplicates");
    s.pop();
    assert(s.getMin() === 2, "min still 2 after popping duplicate");
    s.pop();
    assert(s.size === 0, "empty after popping both duplicates");
  }

  // Negative numbers
  console.log("Negative numbers:");
  {
    const s = new MinStack();
    s.push(-3);
    s.push(0);
    s.push(-5);
    assert(s.getMin() === -5, "min is -5");
    s.pop();
    assert(s.getMin() === -3, "min restored to -3");
  }

  // Push same as current min
  console.log("Push equal to min:");
  {
    const s = new MinStack();
    s.push(1);
    s.push(1);
    assert(s.getMin() === 1, "min with repeated min value");
    s.pop();
    assert(s.getMin() === 1, "min stays 1");
  }

  // Large descending sequence
  console.log("Large sequence:");
  {
    const s = new MinStack();
    for (let i = 100; i >= 1; i--) {
      s.push(i);
    }
    assert(s.getMin() === 1, "min is 1 after pushing 100..1");
    assert(s.top() === 1, "top is 1");
    for (let i = 0; i < 50; i++) s.pop();
    assert(s.getMin() === 51, "min is 51 after popping 50 elements");
    assert(s.top() === 51, "top is 51");
  }

  // All same value
  console.log("All same value:");
  {
    const s = new MinStack();
    for (let i = 0; i < 10; i++) s.push(7);
    assert(s.getMin() === 7, "min is 7 for all-same stack");
    for (let i = 0; i < 9; i++) s.pop();
    assert(s.getMin() === 7, "min is 7 with one element left");
  }

  // Empty stack errors
  console.log("Error handling:");
  {
    const s = new MinStack();
    let threw;
    threw = false;
    try { s.pop(); } catch (e) { threw = true; }
    assert(threw, "pop on empty throws");
    threw = false;
    try { s.top(); } catch (e) { threw = true; }
    assert(threw, "top on empty throws");
    threw = false;
    try { s.getMin(); } catch (e) { threw = true; }
    assert(threw, "getMin on empty throws");
  }

  // Interleaved push/pop/getMin
  console.log("Interleaved push/pop/getMin:");
  {
    const s = new MinStack();
    s.push(5);  // [5]
    s.push(3);  // [5,3]
    assert(s.getMin() === 3, "min=3");
    s.push(7);  // [5,3,7]
    assert(s.getMin() === 3, "min=3 after push 7");
    s.pop();    // [5,3]
    assert(s.top() === 3, "top=3 after pop");
    s.push(1);  // [5,3,1]
    assert(s.getMin() === 1, "min=1 after push 1");
    s.pop();    // [5,3]
    assert(s.getMin() === 3, "min=3 after pop 1");
    s.pop();    // [5]
    assert(s.getMin() === 5, "min=5 after pop 3");
  }

  // Single element push/pop cycle
  console.log("Push/pop cycle:");
  {
    const s = new MinStack();
    s.push(42);
    assert(s.getMin() === 42, "min=42");
    assert(s.top() === 42, "top=42");
    assert(s.pop() === 42, "pop returns 42");
    assert(s.size === 0, "empty after pop");
    s.push(99);
    assert(s.getMin() === 99, "min=99 after reuse");
  }

  // Descending then ascending
  console.log("Descending then ascending:");
  {
    const s = new MinStack();
    s.push(10);
    s.push(8);
    s.push(6);
    s.push(4);
    s.push(2);
    assert(s.getMin() === 2, "min=2 at bottom of descent");
    s.push(4);
    s.push(6);
    assert(s.getMin() === 2, "min still 2 during ascent");
    for (let i = 0; i < 5; i++) s.pop();
    assert(s.getMin() === 8, "min=8 after popping back to 10,8");
  }

  console.log("\nResults: " + passed + " passed, " + failed + " failed");
  if (failed > 0) process.exit(1);
}

runTests();
